	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.giftCardSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for GiftCard : " + successValue.getGiftCardId());
							  if (successValue.getGiftCardId().equals(giftCardId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfGiftCardList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("GiftCard test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on giftCard consumed")
					);
			subscriber.giftCardSubscribe( giftCardId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for GiftCard : " + successValue.getGiftCardId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfGiftCardList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on giftCard for giftCardId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a GiftCard. 
	 */
	protected GiftCard read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created GiftCard" );

		GiftCard entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read GiftCard with primary key" );
		msg.append( giftCardId );
		
		GiftCardFetchOneSummary fetchOneSummary = new GiftCardFetchOneSummary( giftCardId );

		try {
			entity = GiftCardService.getGiftCardInstance().getGiftCard( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found GiftCard " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a GiftCard.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a GiftCard." );

		StringBuilder msg = new StringBuilder( "Failed to update a GiftCard : " );        
		GiftCard entity = read();
		UpdateGiftCardCommand command = generateUpdateCommand();
		command.setGiftCardId(entity.getGiftCardId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created GiftCard." );

			// for use later on...
			giftCardId = entity.getGiftCardId();

			GiftCardService proxy = GiftCardService.getGiftCardInstance();  

			proxy.updateGiftCard( command ).get();

			LOGGER.info( "-- Successfully saved GiftCard - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + giftCardId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a GiftCard.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created GiftCard." );

		GiftCard entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read GiftCard with id " + giftCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read GiftCard with id " + giftCardId );

			throw e;
		}

		try{
			GiftCardService.getGiftCardInstance().delete( new DeleteGiftCardCommand( entity.getGiftCardId() ) ).get();
			LOGGER.info( "-- Successfully deleted GiftCard with id " + giftCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete GiftCard with id " + giftCardId );

			throw e;
		}
	}

	/**
	 * get all GiftCards.
	 */
	protected List<GiftCard> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of GiftCards:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all GiftCard : " );        
		List<GiftCard> collection  = new ArrayList<>();

		try {
			// call the static get method on the GiftCardService
			collection = GiftCardService.getGiftCardInstance().getAllGiftCard();
			assertNotNull( collection, "An Empty collection of GiftCard was incorrectly returned.");
			
			// Now print out the values
			GiftCard entity = null;            
			Iterator<GiftCard> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getGiftCardId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

